var raw = msg.payload;
if (Buffer.isBuffer(raw)) raw = raw.toString();
var lines = raw.split(String.fromCharCode(10));
for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (line.indexOf("event: ") === 0) {
        flow.set("sse_event", line.substring(7).trim());
    }
    if (line.indexOf("data: ") === 0) {
        try {
            var newMsg = {
                event: flow.get("sse_event") || "unknown",
                payload: JSON.parse(line.substring(6))
            };
            node.send(newMsg);
        } catch(e) {}
    }
}
return null;
